<script>
  import { onMount } from 'svelte';
  import { carregar, brl, lerEstado, gravarEstado, criarPerfil, escolherPessoaMigrada, pessoaLocal, parceiro, desvincular, registrarEvento, QUALIDADE_PADRAO } from '$lib/dados.js';
  import { TIPOS, TIPO_LABEL, flag } from '$lib/filtros.js';
  import { criarPacote, importarPacote, linkComPacote, pacoteDoHash } from '$lib/troca.js';
  import { passaQualidade, pontuarDupla } from '$lib/ranking.js';

  let local = $state(lerEstado()); let dados = $state(null); let erro = $state(''); let aba = $state('inicio');
  let nome = $state(''); let cidade = $state('São Paulo'); let perfil = $state(false); let preferencias = $state(false); let ajustes = $state(false);
  let feedback = $state(null); let motivos = $state([]); let nota = $state(''); let aviso = $state(''); let filtroQualidade = $state(true);
  const eu = $derived(pessoaLocal(local)); const outra = $derived(parceiro(local));
  const pessoas = $derived(Object.values(local.pessoas ?? {}));
  const naoVistos = $derived(local.eventos.filter((e) => e.pessoaId !== local.aparelho.pessoaId && !local.eventosVistos.includes(e.id)));
  const pendentes = $derived(local.eventos.filter((e) => e.pessoaId === local.aparelho.pessoaId && (!local.ultimoCompartilhamento || e.criadoEm > local.ultimoCompartilhamento)));
  const ofertas = $derived((dados?.ofertas ?? []).filter((o) => !local.descartados.includes(o.id)).map((o) => ({ ...o, itemTipo: 'viagem', ranking: pontuarDupla(o, pessoas, local.gosto, local.eventos) })).sort((a,b)=>b.ranking.pontos-a.ranking.pontos));
  const escapadas = $derived((dados?.escapadas ?? []).map((e) => ({ ...e, itemTipo: 'escapada', ranking: pontuarDupla(e, pessoas, local.gosto, local.eventos) })).filter((e) => !filtroQualidade || pessoas.every((p) => passaQualidade(e, p.qualidade ?? QUALIDADE_PADRAO))).sort((a,b)=>b.ranking.pontos-a.ranking.pontos));

  function salvar(e) { local = e; gravarEstado(local); }
  onMount(async () => {
    local = lerEstado(); perfil = !local.aparelho.pessoaId && !local.migracao?.precisaEscolherPessoa;
    try { const pacote = pacoteDoHash(location.hash); if (pacote) { const r = importarPacote(local, pacote); salvar(r.estado); aviso = r.novos.length ? `${pacote.remetente.nome} enviou ${r.novos.length} novidade${r.novos.length>1?'s':''}.` : `Vínculo com ${pacote.remetente.nome} atualizado.`; history.replaceState(null, '', location.pathname + location.search); } } catch (e) { aviso = e.message; }
    try { dados = await carregar(); } catch (e) { erro = e.message; }
  });
  function concluirPerfil() { if (!nome.trim() || !cidade) return; salvar(criarPerfil(local, { nome, cidade })); perfil = false; preferencias = true; }
  function toggleGosto(tipo) { const id = local.aparelho.pessoaId; const atual = local.gosto[id] ?? []; salvar({ ...local, gosto: { ...local.gosto, [id]: atual.includes(tipo) ? atual.filter((x)=>x!==tipo) : [...atual,tipo] } }); }
  function atualizarQualidade(campo, valor) { const p = { ...eu, qualidade: { ...QUALIDADE_PADRAO, ...eu.qualidade, [campo]: valor }, atualizadoEm: new Date().toISOString() }; salvar({ ...local, pessoas: { ...local.pessoas, [p.id]: p } }); }
  function avaliar(item, acao) { feedback = { item, acao }; motivos = []; nota = ''; }
  function concluirFeedback() {
    const { item, acao } = feedback; let e = registrarEvento(local, { itemId: item.id, itemTipo: item.itemTipo, acao, motivos, nota });
    if (acao === 'salvei') e = item.itemTipo === 'escapada' ? { ...e, escapadasFavoritas: [...new Set([...e.escapadasFavoritas,item.id])] } : { ...e, favoritos: [...new Set([...e.favoritos,item.id])] };
    if (acao === 'descartei') e = { ...e, descartados: [...new Set([...e.descartados,item.id])] };
    salvar(e); feedback = null;
  }
  async function compartilhar(tipo = local.dupla.status === 'pareada' ? 'atualizacao' : 'convite') {
    try { const pacote = criarPacote(local, tipo); const url = linkComPacote(location.href, pacote); const text = tipo === 'convite' ? `${eu.nome} convidou você para o Viagem para Dois.` : `${eu.nome} marcou novidades no Viagem para Dois.`;
      if (navigator.share) await navigator.share({ title: 'Viagem para Dois', text, url }); else window.open(`https://wa.me/?text=${encodeURIComponent(`${text}\n${url}`)}`, '_blank', 'noopener');
      salvar({ ...local, dupla: { ...local.dupla, id: pacote.duplaId, status: local.dupla.status === 'pareada' ? 'pareada' : 'convidou' }, ultimoCompartilhamento: new Date().toISOString() });
    } catch (e) { if (e.name !== 'AbortError') aviso = e.message; }
  }
  function marcarVistos() { salvar({ ...local, eventosVistos: [...new Set([...local.eventosVistos, ...naoVistos.map((e)=>e.id)])] }); }
  function confirmarDesvinculo() { if (confirm(`Desvincular de ${outra?.nome ?? 'esta pessoa'}? Seu perfil e suas escolhas serão preservados.`)) { salvar(desvincular(local)); ajustes = false; aviso = 'Dupla desvinculada. Você já pode convidar outra pessoa.'; } }
  const razoes = (tipo) => tipo === 'escapada' ? ['localização','avaliação','estrelas','preço','estilo','comodidades'] : ['destino','preço','datas','classe do voo','escalas','estilo'];
</script>

<svelte:head><title>Viagem para Dois — achados para escapar juntos</title><meta name="description" content="Achados de viagens e escapadas escolhidos para vocês dois." /></svelte:head>

<header class="topbar"><button class="brand" onclick={()=>aba='inicio'}><span>◎</span><b>Viagem para Dois<small>Achados para escapar juntos.</small></b></button>{#if eu}<button class="identity" onclick={()=>ajustes=true}><i>{eu.nome[0]}</i><span>{outra ? `${eu.nome} + ${outra.nome}` : eu.nome}<small>{local.dupla.cidade} · ajustar</small></span>{#if naoVistos.length}<em>{naoVistos.length}</em>{/if}</button>{/if}</header>
{#if aviso}<div class="notice"><span>{aviso}</span><button onclick={()=>aviso=''}>×</button></div>{/if}
{#if naoVistos.length}<section class="activity"><b>💛 {outra?.nome ?? 'Sua dupla'} marcou {naoVistos.length} novidade{naoVistos.length>1?'s':''}</b><p>Veja as escolhas recebidas e procurem os matches.</p><button onclick={marcarVistos}>Marcar como vistas</button></section>{/if}
{#if eu}<nav>{#each [['inicio','Para vocês'],['escapadas','Escapadas'],['viagens','Viagens'],['salvos','Salvos']] as [id,label]}<button class:on={aba===id} onclick={()=>aba=id}>{label}{id==='salvos' && (local.favoritos.length+local.escapadasFavoritas.length) ? ` ${local.favoritos.length+local.escapadasFavoritas.length}`:''}</button>{/each}</nav>{/if}

{#if erro}<main class="empty"><b>Não foi possível atualizar os achados.</b><p>{erro}</p></main>{:else if !dados}<main class="empty">Carregando os achados…</main>{:else if eu}
<main>
  {#if aba==='inicio'}
    <section class="hero"><p>OLÁ, {eu.nome.toUpperCase()}</p><h1>O próximo <em>sim</em><br/>começa aqui.</h1><span>{outra ? `Recomendações para ${eu.nome} e ${outra.nome}, com o equilíbrio entre os dois.` : 'Configure seus gostos e convide a outra pessoa pelo WhatsApp.'}</span><div class="heroactions"><button onclick={()=>preferencias=true}>Minhas preferências</button><button class="primary" onclick={()=>compartilhar()}>{outra ? `Enviar novidades${pendentes.length?` (${pendentes.length})`:''}`:'Convidar pelo WhatsApp'}</button></div></section>
    <h2 class="sectiontitle">Melhores combinações</h2><div class="grid">{#each ofertas.slice(0,4) as o}<article class="card"><header><span>{flag(o.pais_iso2)}</span><div><h3>{o.destino_texto}</h3><small>{o.ranking.pontos}% de afinidade</small></div></header><p>{o.ranking.explicacao}</p><b>{brl(o.preco_brl*(o.por_pessoa?2:1))}<small> para dois</small></b><div class="actions"><button onclick={()=>avaliar(o,'nao_gostei')}>👎</button><button onclick={()=>avaliar(o,'gostei')}>👍</button><button onclick={()=>avaliar(o,'salvei')}>Salvar</button><a href={o.fontes[0].link} target="_blank" rel="noopener">Ver ↗</a></div></article>{/each}</div>
  {:else if aba==='escapadas'}
    <section class="intro"><p>PERTO DE {local.dupla.cidade.toUpperCase()}</p><h1>Uma pausa cabe<br/>neste fim de semana.</h1><span>Hotel na cidade, bate-e-volta ou dois dias por perto.</span></section>
    <section class="filter"><label><input type="checkbox" bind:checked={filtroQualidade}/> Aplicar o padrão de qualidade da dupla</label><button onclick={()=>ajustes=true}>Ajustar padrão</button></section>
    {#if !escapadas.length}<div class="empty"><b>Nenhuma opção passou pelos filtros.</b><p>Você pode aceitar hotéis sem classificação ou reduzir os mínimos nos ajustes.</p></div>{/if}
    <div class="grid">{#each escapadas as e}<article class="card"><header><span>{e.icone}</span><div><h3>{e.nome}</h3><small>{e.destino} · {e.estrelas?`${e.estrelas} estrelas`:'sem estrelas informadas'}</small></div></header><p>★ {e.avaliacao ?? '—'} ({e.avaliacoes ?? 0} avaliações) · {e.ranking.pontos}% de afinidade</p><b>{brl(e.preco_total)}<small> para dois</small></b><div class="actions"><button onclick={()=>avaliar(e,'nao_gostei')}>👎</button><button onclick={()=>avaliar(e,'gostei')}>👍</button><button onclick={()=>avaliar(e,'salvei')}>Salvar</button><a href={e.link} target="_blank" rel="noopener">Ver ↗</a></div></article>{/each}</div>
  {:else if aba==='viagens'}
    <section class="intro"><p>RADAR DE OPORTUNIDADES</p><h1>Escolhas melhores,<br/>não só mais baratas.</h1><span>O ranking considera preferências e o feedback de cada pessoa.</span></section><div class="grid">{#each ofertas as o}<article class="card"><header><span>{flag(o.pais_iso2)}</span><div><h3>{o.destino_texto}</h3><small>{o.escalas===0?'voo direto':`${o.escalas??'?'} escala(s)`}</small></div></header><p>{o.ranking.explicacao} · {o.ranking.pontos}%</p><b>{brl(o.preco_brl*(o.por_pessoa?2:1))}</b><div class="actions"><button onclick={()=>avaliar(o,'nao_gostei')}>👎</button><button onclick={()=>avaliar(o,'gostei')}>👍</button><button onclick={()=>avaliar(o,'salvei')}>Salvar</button><button onclick={()=>avaliar(o,'descartei')}>Ocultar</button></div></article>{/each}</div>
  {:else}
    <section class="intro"><p>ESCOLHIDOS POR VOCÊS</p><h1>Planos para<br/>conversar depois.</h1></section><div class="grid">{#each [...ofertas.filter((o)=>local.favoritos.includes(o.id)), ...(dados.escapadas??[]).filter((e)=>local.escapadasFavoritas.includes(e.id))] as item}<article class="card"><h3>{item.destino_texto??item.nome}</h3><p>{item.destino??item.janela??'Escolha salva'}</p></article>{/each}</div>
  {/if}
</main>{/if}

{#if perfil}<div class="backdrop"></div><section class="modal"><p>SEU ESPAÇO</p><h2>Primeiro, conte<br/>sobre você.</h2><span>Cada pessoa configura o próprio aparelho. Depois vocês trocam um convite pelo WhatsApp.</span><label>Seu nome<input bind:value={nome} autocomplete="given-name" placeholder="Como podemos chamar você?"/></label><label>Cidade-base<select bind:value={cidade}><option>São Paulo</option></select></label><button class="primary wide" disabled={!nome.trim()} onclick={concluirPerfil}>Criar meu perfil →</button></section>{/if}
{#if local.migracao?.precisaEscolherPessoa}<div class="backdrop"></div><section class="modal"><p>MIGRAÇÃO SEGURA</p><h2>Quem está usando<br/>este aparelho?</h2><span>As escolhas anteriores foram preservadas. Agora cada aparelho precisa saber quem é você.</span>{#each pessoas as p}<button class="choice" onclick={()=>salvar(escolherPessoaMigrada(local,p.id))}>Eu sou {p.nome}</button>{/each}</section>{/if}
{#if preferencias}<div class="backdrop" onclick={()=>preferencias=false}></div><section class="drawer"><button class="close" onclick={()=>preferencias=false}>×</button><p>SUAS PREFERÊNCIAS</p><h2>O que faz uma viagem valer a pena?</h2><div class="tastes">{#each TIPOS as [id,emoji,label]}<button class:on={(local.gosto[eu.id]??[]).includes(id)} onclick={()=>toggleGosto(id)}><span>{emoji}</span>{label}</button>{/each}</div><button class="primary wide" onclick={()=>{preferencias=false;if(!outra)compartilhar('convite')}}>{outra?'Salvar preferências':'Salvar e convidar'}</button></section>{/if}
{#if ajustes}<div class="backdrop" onclick={()=>ajustes=false}></div><section class="drawer"><button class="close" onclick={()=>ajustes=false}>×</button><p>QUALIDADE E DUPLA</p><h2>Seu padrão de viagem</h2><label>Hotel: mínimo de estrelas <select value={eu.qualidade?.hotelEstrelas??4} onchange={(e)=>atualizarQualidade('hotelEstrelas',+e.currentTarget.value)}><option value="3">3</option><option value="4">4</option><option value="5">5</option></select></label><label>Avaliação mínima <select value={eu.qualidade?.avaliacaoMinima??4.3} onchange={(e)=>atualizarQualidade('avaliacaoMinima',+e.currentTarget.value)}><option value="4">4,0</option><option value="4.3">4,3</option><option value="4.5">4,5</option><option value="4.7">4,7</option></select></label><label>Mínimo de avaliações <select value={eu.qualidade?.minimoAvaliacoes??100} onchange={(e)=>atualizarQualidade('minimoAvaliacoes',+e.currentTarget.value)}><option value="20">20</option><option value="100">100</option><option value="300">300</option></select></label><label><input type="checkbox" checked={eu.qualidade?.aceitarSemClassificacao??false} onchange={(e)=>atualizarQualidade('aceitarSemClassificacao',e.currentTarget.checked)}/> Aceitar hotel sem estrelas informadas</label><label>Classe da passagem <select value={eu.qualidade?.classeVoo??'economica'} onchange={(e)=>atualizarQualidade('classeVoo',e.currentTarget.value)}><option value="economica">Econômica</option><option value="premium">Econômica premium</option><option value="executiva">Executiva</option></select><small>Aplicada apenas quando a fonte informa a classe.</small></label><hr/>{#if outra}<button class="danger" onclick={confirmarDesvinculo}>Desvincular de {outra.nome}</button>{:else}<button class="primary wide" onclick={()=>compartilhar('convite')}>Convidar alguém</button>{/if}</section>{/if}
{#if feedback}<div class="backdrop"></div><section class="modal"><p>{feedback.acao==='nao_gostei'?'NÃO FAZ SEU ESTILO':'CONTE MAIS'}</p><h2>Por quê?</h2><span>Isso melhora as próximas sugestões. A observação livre fica somente neste aparelho.</span><div class="chips">{#each razoes(feedback.item.itemTipo) as r}<button class:on={motivos.includes(r)} onclick={()=>motivos=motivos.includes(r)?motivos.filter((x)=>x!==r):[...motivos,r]}>{r}</button>{/each}</div><label>Observação opcional<textarea bind:value={nota} placeholder="Ex.: muito simples para uma ocasião especial"></textarea></label><button class="primary wide" onclick={concluirFeedback}>Registrar escolha</button><button class="link" onclick={()=>feedback=null}>Cancelar</button></section>{/if}

<style>
  :global(*){box-sizing:border-box}:global(body){margin:0;background:#07101c;color:#edf3fb;font-family:Inter,system-ui,sans-serif}:global(button),:global(input),:global(select),:global(textarea){font:inherit}.topbar,nav,main,.activity{width:min(1000px,calc(100% - 32px));margin:auto}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between}.brand,.identity{border:0;background:none;color:inherit;display:flex;align-items:center;gap:10px;text-align:left}.brand>span{border:1px solid #f5a524;border-radius:10px;padding:7px;color:#f5a524}.brand small,.identity small{display:block;color:#7f91aa;font-size:10px}.identity{background:#101b2c;border:1px solid #203149;border-radius:12px;padding:7px 10px}.identity i{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#17405b;font-style:normal}.identity em{background:#f5a524;color:#111;border-radius:99px;padding:2px 6px;font-style:normal;font-size:10px}.notice{background:#2b2412;color:#ffe2a0;padding:10px 16px;display:flex;justify-content:center;gap:20px;font-size:12px}.notice button{background:none;border:0;color:inherit}.activity{margin-top:10px;border:1px solid #5a481d;background:#211e13;border-radius:14px;padding:13px;display:flex;align-items:center;gap:12px}.activity p{flex:1;margin:0;color:#baa979;font-size:11px}.activity button,.filter button{border:0;background:#f5a524;border-radius:8px;padding:8px 10px;font-size:10px}nav{display:flex;gap:22px;border-bottom:1px solid #1b2a40;overflow:auto}nav button{padding:13px 2px;border:0;border-bottom:2px solid transparent;background:none;color:#778ba5;white-space:nowrap}nav button.on{color:#f5a524;border-color:#f5a524}main{padding:30px 0 70px}.hero,.intro{padding:35px 0}.hero>p,.intro>p,.modal>p,.drawer>p{font-size:10px;letter-spacing:.18em;color:#f5a524;font-weight:800}.hero h1,.intro h1,.modal h2,.drawer h2{font-family:Georgia,serif;font-size:clamp(40px,7vw,68px);line-height:.98;font-weight:500;margin:10px 0}.hero h1 em{color:#f5a524}.hero>span,.intro>span,.modal>span{color:#8b9cb2;line-height:1.6;font-size:13px}.heroactions{display:flex;gap:8px;margin-top:20px}.heroactions button,.primary{border:1px solid #344761;background:#142138;color:#fff;border-radius:10px;padding:11px 14px}.primary{background:#f5a524!important;color:#111!important;border:0!important;font-weight:700}.sectiontitle{font-family:Georgia,serif;font-weight:500}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{border:1px solid #22334d;background:#101b2c;border-radius:17px;padding:16px}.card header{display:flex;align-items:center;gap:10px}.card header>span{font-size:28px}.card h3{margin:0;font-size:16px}.card small,.card p{color:#8294ab;font-size:10px}.card p{min-height:28px}.actions{display:flex;gap:6px;margin-top:14px}.actions button,.actions a{border:0;background:#1d2d45;color:#d9e2ed;text-decoration:none;padding:8px;border-radius:8px;font-size:10px}.actions a{margin-left:auto;background:#f5a524;color:#111}.filter{border:1px solid #263852;background:#0d1726;border-radius:13px;padding:10px 13px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;font-size:11px}.empty{text-align:center;color:#8294ab;padding:60px 20px}.backdrop{position:fixed;inset:0;background:#040912dd;z-index:20}.modal,.drawer{position:fixed;z-index:21;background:#101b2c;border:1px solid #293a55;padding:28px;box-shadow:0 30px 90px #000b}.modal{inset:50% auto auto 50%;transform:translate(-50%,-50%);width:min(440px,calc(100% - 28px));border-radius:22px}.modal h2,.drawer h2{font-size:32px}.modal label,.drawer label{display:block;color:#9aabc0;font-size:11px;margin-top:13px}.modal input,.modal select,.modal textarea,.drawer select{width:100%;margin-top:5px;background:#091421;border:1px solid #30425d;color:#fff;border-radius:10px;padding:11px}.modal textarea{min-height:70px}.wide{width:100%;margin-top:18px}.choice{width:100%;margin-top:8px;border:1px solid #344761;background:#142138;color:#fff;border-radius:10px;padding:12px}.drawer{right:0;top:0;bottom:0;width:min(500px,100%);overflow:auto}.close{float:right;border:0;background:none;color:#fff;font-size:24px}.tastes{display:grid;grid-template-columns:1fr 1fr;gap:7px}.tastes button,.chips button{border:1px solid #293a55;background:#121f33;color:#dce5ef;border-radius:10px;padding:10px;text-align:left}.tastes button.on,.chips button.on{border-color:#f5a524;background:#292716}.tastes span{margin-right:8px}.chips{display:flex;flex-wrap:wrap;gap:6px}.chips button{padding:7px 9px;font-size:10px}.drawer hr{border:0;border-top:1px solid #293a55;margin:22px 0}.danger{width:100%;border:1px solid #773f46;background:#321a20;color:#ffb8c0;border-radius:10px;padding:11px}.link{width:100%;border:0;background:none;color:#8fa0b6;padding:10px}.drawer label small{display:block;margin-top:4px}.drawer input[type=checkbox]{width:auto;margin-right:6px}
  @media(max-width:700px){.topbar{height:62px}.brand small,.identity span{display:none}.activity{align-items:flex-start;flex-wrap:wrap}.activity p{flex-basis:60%}.grid{grid-template-columns:1fr}.hero,.intro{padding:25px 0}.hero h1,.intro h1{font-size:44px}.heroactions{flex-direction:column}.filter{align-items:flex-start;gap:8px}.tastes{grid-template-columns:1fr 1fr}}
</style>
